package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Reopens a closed period, making its due-total, and each person's figure and carried figure, live again. Only a role the permission matrix allows (by
 * the standing rule, a steward) may reopen; a period that
 * is not closed is refused.
 */
public class ReopenPeriod {
    public void reopen(@Val Sheet sheet, @Val Period period, PeriodRepository periods, RoleRepository roles, SettingsRepository settings,
            HttpServletRequest request, Out<Period> reopenedOut) throws InvalidPeriodException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("reopen", role)) {
            throw new InvalidPeriodException("A " + role + " may not reopen period " + period.name());
        }
        if (!period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        Period reopened = period.reopen();
        if (!periods.markReopened(reopened)) {
            throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        }
        periods.deletePersonTotals(reopened);
        periods.deletePersonCarried(reopened);
        reopenedOut.set(reopened);
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the reopened period. */
public class AuditPeriodReopened {
    public void audit(@Val Sheet sheet, @Val Period period, HttpServletRequest request, Audit audit) {
        audit.record("PERIOD_REOPENED sheet=" + sheet.id() + " by=" + Audit.user(request) + " period=" + period.name());
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Soft-closes an open period: its due-total and each person's figure are fixed as a close fixes them,
 * but claims dated inside it can still be added, edited, opened, settled and voided. The same roles
 * as may close may soft-close; a period already closed or soft-closed is refused.
 */
public class SoftClosePeriod {
    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, RoleRepository roles,
            HttpServletRequest request, Out<Period> closedOut) throws InvalidPeriodException {
        String role = roles.roleOf(sheet.id(), Audit.user(request));
        if (!settings.find(sheet.id()).allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " may not soft-close period " + period.name());
        }
        if (period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        Period closed = ClosePeriod.fix(sheet, period, true, periods, people, claims, log, rates, settings);
        if (closed == null) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        closedOut.set(closed);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A period on a sheet: its name (unique on the sheet), its from and to dates, inclusive, whether it
 * is closed, and the due-total fixed when it was closed (null while open). A soft-closed period is
 * closed with {@code soft} set: its figures are fixed, but claims dated inside it can still change.
 * Its cap, when set, is the most OPEN or PENDING claims a person may have due by a date in it.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft, Integer cap) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, null);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to, false, null, false, cap);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
            BigDecimal closedTotal, boolean soft) {
        this(sheetId, name, from, to, closed, closedTotal, soft, null);
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** This period, closed with its due-total fixed. */
    public Period close(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, false, cap);
    }

    /** This period, soft-closed with its due-total fixed. */
    public Period softClose(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, true, cap);
    }

    /** Whether it is closed for good: claims dated inside it cannot change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** This period, reopened: its due-total live again. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, false, cap);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import net.officefloor.hq.app.setting.Settings;

/**
 * A period, as the screen reads it: its name, its from and to dates (yyyy-MM-dd), whether it is
 * closed, the due-total fixed when it was closed ("" while open), and each person's due-total fixed
 * when it was closed, by person id (empty while open), and whether it is soft-closed (closed, its
 * claims still open to change), and the fiscal year its from-date falls in (FY<yyyy>), and its cap
 * ("" for none), and each person's carried figure fixed when it was closed, by person id (empty while open),
 * and each person's opening balance for it, by person id.
 */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals, boolean soft, String fy, String cap, Map<String, String> personCarried,
        Map<String, String> personOpenings) {
    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
            Map<Long, BigDecimal> personOpenings, Settings settings) {
        Map<String, String> totals = new LinkedHashMap<>();
        personTotals.forEach((id, total) -> totals.put(String.valueOf(id), total.setScale(2).toPlainString()));
        Map<String, String> carried = new LinkedHashMap<>();
        personCarried.forEach((id, figure) -> carried.put(String.valueOf(id), figure.setScale(2).toPlainString()));
        Map<String, String> openings = new LinkedHashMap<>();
        personOpenings.forEach((id, amount) -> openings.put(String.valueOf(id), amount.setScale(2).toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(),
                period.closed(), period.closedTotal() == null ? "" : period.closedTotal().setScale(2).toPlainString(),
                totals, period.soft(), settings.fiscalYearOf(period.from()),
                period.cap() == null ? "" : String.valueOf(period.cap()), carried, openings);
    }
}
